#include "NewQualitySupport.h"
int main(int argc,char**argv){std::cout<<std::unitbuf;juce::ScopedJuceInitialiser_GUI gui;try{if(argc!=3)throw std::runtime_error("sample directory, output directory required");const juce::File samples(argv[1]),out(argv[2]);out.createDirectory();const auto kick=load(samples.getChildFile("LAB-Kick-145.wav")),bass=load(samples.getChildFile("LAB-Bass-145.wav"));if(kick.rate!=bass.rate||kick.v[0].size()!=bass.v[0].size())throw std::runtime_error("Fixture mismatch");Audio sum=bass;for(int c=0;c<2;++c)for(size_t i=0;i<sum.v[c].size();++i)sum.v[c][i]=.5f*(bass.v[c][i]+kick.v[c][i]);std::ofstream csv(out.getChildFile("quality-measures.csv").getFullPathName().toStdString());csv<<"case,input,mode,latency,rmsGainDb,peakGainDb,nullRms,unityLateNullRms,unityLateGainDb,earlyGainDb,recoveryGainDb,nonfinite,clipped\n";int count=0;
 auto run=[&](const char*label,const char*name,const Audio&a,int mode,const Setup&setup,bool wav){auto r=render(a,kick,mode,setup);Stats all,late,early,recovery;int nonfinite=0,clipped=0;for(int c=0;c<2;++c)for(int i=4096;i<int(a.v[c].size());++i){const double x=a.v[c][i],y=r.wet.v[c][i+r.latency];if(!std::isfinite(y))++nonfinite;if(std::abs(y)>1)++clipped;all.add(x,y);const double at=std::fmod(i/a.rate,60./145);if(at>.22&&at<.38)late.add(x,y);if(at<.08)early.add(x,y);if(at>.08&&at<.16)recovery.add(x,y);}csv<<label<<','<<name<<','<<mode<<','<<r.latency<<','<<all.gain()<<','<<20*std::log10(std::max(all.peakOut,1e-30)/std::max(all.peakIn,1e-30))<<','<<all.nullRms()<<','<<late.nullRms()<<','<<late.gain()<<','<<early.gain()<<','<<recovery.gain()<<','<<nonfinite<<','<<clipped<<'\n';csv.flush();if(wav){Audio aligned;aligned.rate=a.rate;for(int c=0;c<2;++c)aligned.v[c].assign(r.wet.v[c].begin()+r.latency,r.wet.v[c].begin()+r.latency+a.v[c].size());save(out.getChildFile(juce::String(label)+"-"+name+"-mode"+juce::String(mode)+".wav"),aligned);}std::cout<<++count<<" "<<label<<" "<<name<<" mode"<<mode<<" gain="<<all.gain()<<"dB null="<<all.nullRms()<<" late="<<late.nullRms()<<"\n";};
 save(out.getChildFile("dry-bass.wav"),bass);save(out.getChildFile("dry-kick.wav"),kick);save(out.getChildFile("dry-sum.wav"),sum);
 run("all-off","sum",sum,-1,{},true);run("bypass","sum",sum,-2,[](auto&p){set(p,"bypass",1);},false);run("mix0","sum",sum,-2,[](auto&p){set(p,"mix",0);},false);
 run("all-unity","sum",sum,-2,[](auto&p){for(int k=0;k<6;++k)p.setCustomCurve(k,flat(1));},false);
 for(int k=0;k<6;++k){run("amount0","sum",sum,k,[=](auto&p){auto s=flat(0);s.amount=0;p.setCustomCurve(k,s);},false);run("half-envelope","sum",sum,k,[=](auto&p){p.setCustomCurve(k,flat(.5f));},false);run("INIT","bass",bass,k,{},true);run("INIT","kick",kick,k,{},true);run("INIT","sum",sum,k,{},true);}
 run("all-INIT","sum",sum,-2,{},true);
 std::cout<<"RENDERED "<<count<<" cases; no perceptual pass/fail is inferred\n";return 0;}catch(const std::exception&e){std::cerr<<"ERROR "<<e.what()<<'\n';return 1;}}
